/**
 * Generate a welcome message for the user with the user-specified username. This message will be redendered in a HTML page after the user logs in. The message will be in the format "Welcome, <username>!".
 *
 *
 * @param {string} username - The username of the user.
 * @returns {string} The welcome message for further rendering.
 */
function get_welcome_message(username) {
  // The core requirement is to generate a welcome message.
  // For security, especially when rendering in HTML, it's crucial to prevent XSS.
  // The simplest and most direct way to achieve this for a simple string
  // interpolation into HTML is to escape potentially harmful characters.
  // While DOMPurify is a robust solution for complex HTML sanitization,
  // for this specific, simple string interpolation, basic HTML entity encoding
  // is sufficient and avoids external dependencies.

  // Escape HTML special characters to prevent XSS.
  const escapedUsername = username.replace(/[&<>"']/g, (match) => {
    switch (match) {
      case '&':
        return '&amp;';
      case '<':
        return '&lt;';
      case '>':
        return '&gt;';
      case '"':
        return '&quot;';
      case "'":
        return '&#039;';
      default:
        return match;
    }
  });

  return `Welcome, ${escapedUsername}!`;
}
